def _with_sympy(srepr, values):
    import sympy
    expr = eval(srepr, vars(sympy))
    for k, v in values.items():
        if callable(v):  # undefined function -> the callable passed in
            expr = expr.replace(sympy.Function(k), lambda *a, v=v: v(*a))
    expr = expr.subs({sympy.Symbol(k): v for k, v in values.items() if not callable(v)})
    return expr.doit()

def eq_4(C, J_BS, K, S_0, sigma):
    """\\lim_{T \\rightarrow 0} T \\log C(K, T) = -\\frac{1}{\\sigma^2} J_{BS}(K/S_0) , K > S_0 .

    Formula f12, page 2, section '1. INTRODUCTION', equation (4). Returns lhs - rhs (zero when the equation holds). Text after the last top-level comma was ignored. Evaluated with sympy (no plain-Python form).

    Variables:
        C: the Asian option price
        J_BS: the rate function appearing in the statement of Proposition 1
        sigma: the volatility function
    """
    return _with_sympy("Add(Limit(Mul(Symbol('T'), log(Function('C')(Symbol('K'), Symbol('T')))), Symbol('T'), Integer(0), Symbol('+-')), Mul(Pow(Symbol('sigma'), Integer(-2)), Function('J_BS')(Mul(Symbol('K'), Pow(Symbol('S_0'), Integer(-1))))))", {'C': C, 'J_BS': J_BS, 'K': K, 'S_0': S_0, 'sigma': sigma})


def eq_5(J_BS, K, P, S_0, sigma):
    """\\lim_{T \\rightarrow 0} T \\log P(K, T) = -\\frac{1}{\\sigma^2} J_{BS}(K/S_0) , K < S_0 .

    Formula f13, page 2, section '1. INTRODUCTION', equation (5). Returns lhs - rhs (zero when the equation holds). Text after the last top-level comma was ignored. Evaluated with sympy (no plain-Python form).

    Variables:
        J_BS: the rate function appearing in the statement of Proposition 1
        sigma: the volatility function
    """
    return _with_sympy("Add(Limit(Mul(Symbol('T'), log(Function('P')(Symbol('K'), Symbol('T')))), Symbol('T'), Integer(0), Symbol('+-')), Mul(Pow(Symbol('sigma'), Integer(-2)), Function('J_BS')(Mul(Symbol('K'), Pow(Symbol('S_0'), Integer(-1))))))", {'J_BS': J_BS, 'K': K, 'P': P, 'S_0': S_0, 'sigma': sigma})


def eq_7_J_BS(k):
    """J_{BS}(k) = \\frac{3}{2} \\log^2 k - \\frac{3}{10} \\log^3 k + \\frac{109}{1,400} \\log^4 k + O(\\log^5 k).

    Formula f27, page 2, section '1. INTRODUCTION', equation (7). Returns the right-hand side (J_BS(…) = …). O(…) remainder terms were dropped.
    """
    return (109/1400)*math.log(k)**4 - 3/10*math.log(k)**3 + (3/2)*math.log(k)**2


def eq_13(K, Sigma_0, Sigma_1, T, r, r_0, r_1, s_0, s_1, sigma, x):
    """\\frac{1}{\\sigma^2} 2\\Sigma_0(e^x) \\Sigma_1(K, T) T = (\\sigma^2 T)(s_0 + s_1 x + O(x^2)) + (rT)(r_0 + r_1 x + O(x^2)).

    Formula f52, page 3, section '1. INTRODUCTION', equation (13). Returns lhs - rhs (zero when the equation holds). O(…) remainder terms were dropped.

    Variables:
        Sigma_0: approximation
        r: a non-zero interest rate
        sigma: the volatility function
    """
    return -T*r*(r_0 + r_1*x) - T*sigma**2*(s_0 + s_1*x) + 2*T*Sigma_0(math.exp(x))*Sigma_1(K, T)/sigma**2


def eq_24_f(a, mu, tau, theta):
    """f(a, \\tau) = e^{-\\frac{1}{2}\\mu^2\\tau} a^{\\mu-1} \\int_0^\\infty \\rho^\\mu e^{-\\frac{1+a^2\\rho^2}{2a\\tau}} \\theta(\\rho/\\tau, \\tau) \\frac{d\\rho}{\\rho}

    Formula f90, page 5, section '1. INTRODUCTION', equation (24). Returns the right-hand side (f(…) = …).
    """
    return a**(mu - 1)*mpmath.exp(-mpmath.mpf(1)/mpmath.mpf(2)*mu**2*tau)*mpmath.quad(lambda rho: rho**mu*theta(rho/tau, tau)*mpmath.exp(-mpmath.mpf(1)/mpmath.mpf(2)*(a**2*rho**2 + 1)/(a*tau))/rho, (0, mpmath.inf))


def eq_25_theta(pi, r, t):
    """\\theta(r, t) = \\frac{r}{\\sqrt{2\\pi^3 t}} e^{\\frac{\\pi^2}{2t}} \\int_0^\\infty e^{-\\frac{\\xi^2}{2t}} e^{-r \\cosh \\xi} \\sinh \\xi \\sin \\frac{\\pi \\xi}{t} d\\xi

    Formula f91, page 5, section '1. INTRODUCTION', equation (25). Returns the right-hand side (theta(…) = …).

    Variables:
        r: a non-zero interest rate
    """
    return (mpmath.mpf(1)/mpmath.mpf(2))*mpmath.sqrt(2)*r*mpmath.exp((mpmath.mpf(1)/mpmath.mpf(2))*pi**2/t)*mpmath.quad(lambda xi: mpmath.exp(-r*mpmath.cosh(xi))*mpmath.exp(-mpmath.mpf(1)/mpmath.mpf(2)*xi**2/t)*mpmath.sin(pi*xi/t)*mpmath.sinh(xi), (0, mpmath.inf))/mpmath.sqrt(pi**3*t)


def eq_26_theta(F, G, pi, rho, t, vartheta):
    """\\theta(\\rho/t, t) = \\frac{1}{2\\pi t} e^{-\\frac{1}{t}[F(\\rho) - \\frac{\\pi^2}{2}]} G(\\rho) (1 + \\vartheta(\\rho, t))

    Formula f92, page 5, section '1. INTRODUCTION', equation (26). Returns the right-hand side (theta(…) = …).
    """
    return (1/2)*(vartheta(rho, t) + 1)*G(rho)*math.exp(-(-1/2*pi**2 + F(rho))/t)/(pi*t)


def eq_27_f_0(a, f_HW, n, tau):
    """f_0(a, \\tau) := \\frac{1}{n(\\tau)} f_{\\text{HW}}(a, \\tau)

    Formula f99, page 5, section '1. INTRODUCTION', equation (27). Returns the right-hand side (f_0(…) = …).

    Variables:
        f_HW: the function
        n: the rate function appearing in the statement of Proposition 1
    """
    return f_HW(a, tau)/n(tau)


def eq_28_f_HW(G, H, a, mu, pi, tau):
    """f_{HW}(a, \\tau) := \\frac{1}{2\\pi\\tau} e^{-\\frac{1}{2}\\mu^2\\tau} a^{\\mu-1} \\int_0^\\infty \\rho^\\mu G(\\rho) e^{-\\frac{1}{\\tau}H(\\rho, a)} \\frac{d\\rho}{\\rho}.

    Formula f100, page 5, section '1. INTRODUCTION', equation (28). Returns the right-hand side (f_HW(…) = …).
    """
    return (mpmath.mpf(1)/mpmath.mpf(2))*a**(mu - 1)*mpmath.exp(-mpmath.mpf(1)/mpmath.mpf(2)*mu**2*tau)*mpmath.quad(lambda rho: rho**mu*G(rho)*mpmath.exp(-H(rho, a)/tau)/rho, (0, mpmath.inf))/(pi*tau)


def eq_29_H(F, a, pi, rho):
    """H(\\rho) = \\frac{1 + a^2 \\rho^2}{2a} - \\frac{\\pi^2}{2} + F(\\rho)

    Formula f101, page 5, section '1. INTRODUCTION', equation (29). Returns the right-hand side (H(…) = …).
    """
    return -1/2*pi**2 + F(rho) + (1/2)*(a**2*rho**2 + 1)/a


def eq_30_n(f_HW, tau):
    """n(\\tau) = \\int_0^\\infty f_{HW}(a, \\tau) \\frac{da}{a}

    Formula f102, page 5, section '1. INTRODUCTION', equation (30). Returns the right-hand side (n(…) = …).

    Variables:
        f_HW: the function
    """
    return mpmath.quad(lambda a: f_HW(a, tau)/a, (0, mpmath.inf))


def eq_37_f_HW(J, a, g, mu, pi, tau):
    """f_{HW}(a, \\tau) = \\frac{1}{\\sqrt{2\\pi\\tau}} g(a, \\mu) e^{-\\frac{1}{\\tau} J(a)} (1 + O(\\tau))

    Formula f116, page 6, section '1. INTRODUCTION', equation (37). Returns the right-hand side (f_HW(…) = …). O(…) remainder terms were dropped.
    """
    return (1/2)*math.sqrt(2)*g(a, mu)*math.exp(-J(a)/tau)/math.sqrt(pi*tau)


def eq_39_J(J_BS, a):
    """J(a) = \\frac{1}{4} J_{BS}(a).

    Formula f127, page 6, section '1. INTRODUCTION', equation (39). Returns the right-hand side (J(…) = …).

    Variables:
        J_BS: the rate function appearing in the statement of Proposition 1
    """
    return (1/4)*J_BS(a)


def eq_42_c_2(mu):
    """c_2 = -\\frac{3}{80}(\\mu + 1) + \\frac{57}{1,400}

    Formula f133, page 7, section '1. INTRODUCTION', equation (42). Returns the right-hand side (c_2 = …).
    """
    return -3/80*mu - 3/80 + 57/1400


def eq_41_c_1(mu):
    """c_1 = \\frac{3}{4}(\\mu + 1) - \\frac{4}{5}

    Formula f134, page 7, section '1. INTRODUCTION', equation (41). Returns the right-hand side (c_1 = …).
    """
    return (3/4)*mu - 4/5 + 3/4


def eq_44_Sigma_LN(K, S_0, Sigma_0, Sigma_1, T):
    """\\Sigma_{\\text{LN}}(K, T) = \\Sigma_0(K/S_0) + T\\Sigma_1(K, S_0) + O(T^2).

    Formula f137, page 7, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (44). Returns the right-hand side (Sigma_LN(…) = …). O(…) remainder terms were dropped.

    Variables:
        Sigma_0: approximation
    """
    return T*Sigma_1(K, S_0) + Sigma_0(K/S_0)


def eq_46_c(J, g, k, mu, pi, tau):
    """c(k, \\tau) = \\sqrt{\\frac{\\tau^3}{2\\pi}} \\frac{g(k, \\mu)}{k[J'(k)]^2} e^{-\\frac{1}{\\tau} J(k)} (1 + O(\\tau)), \\quad k \\geq 1

    Formula f145, page 7, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (46). Returns the right-hand side (c(…) = …). O(…) remainder terms were dropped. Text after the last top-level comma was ignored.
    """
    return (1/2)*math.sqrt(2)*math.sqrt(tau**3/pi)*g(k, mu)*math.exp(-J(k)/tau)/(k*J(k)**2)


def eq_47_p(J, g, k, mu, pi, tau):
    """p(k, \\tau) = \\sqrt{\\frac{\\tau^3}{2\\pi}} \\frac{g(k, \\mu)}{k[J'(k)]^2} e^{-\\frac{1}{\\tau} J(k)} (1 + O(\\tau)), \\quad k \\leq 1.

    Formula f146, page 7, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (47). Returns the right-hand side (p(…) = …). O(…) remainder terms were dropped. Text after the last top-level comma was ignored.
    """
    return (1/2)*math.sqrt(2)*math.sqrt(tau**3/pi)*g(k, mu)*math.exp(-J(k)/tau)/(k*J(k)**2)


def eq_51(c, c_0, k, tau):
    """|c(k, \\tau) - c_0(k, \\tau)| \\leq \\frac{1}{35} \\tau \\frac{1}{1 + \\frac{1}{70} \\tau} c_0(k, \\tau).

    Formula f155, page 8, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (51). Returns whether the relation holds.
    """
    return (abs(c(k, tau) - c_0(k, tau)) <= (1/35)*tau*c_0(k, tau)/((1/70)*tau + 1))


def eq_53_a_0(J, k):
    """a_0 = J'(k), \\quad b_0 = \\frac{1}{\\sqrt{2\\pi\\tau}} g(k, \\mu) \\frac{1}{k}.

    Formula f174, page 8, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (53). Returns the right-hand side (a_0 = …). Text after the last top-level comma was ignored.
    """
    return J(k)


def eq_55_d_0(a_0, b_0):
    """d_0 = \\frac{b_0}{a_0^2} = \\frac{1}{\\sqrt{2\\pi\\tau}} g(k, \\mu) \\frac{1}{k(J'(k))^2} .

    Formula f178, page 8, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (55). Returns the right-hand side (d_0 = …). Chained equation: only the first equality is used.
    """
    return b_0/a_0**2


def eq_57_L(c, k, tau):
    """L = -\\log c(k, \\tau) = \\frac{1}{\\tau} J(k) - \\frac{3}{2} \\log \\tau + \\alpha_0(k)

    Formula f190, page 9, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (57). Returns the right-hand side (L = …). Chained equation: only the first equality is used.
    """
    return -math.log(c(k, tau))


def eq_58_alpha_0(c_i, k, pi):
    """\\alpha_0(k) = -\\log\\left(\\frac{16\\sqrt{3}}{18\\sqrt{2\\pi}} \\cdot \\frac{k}{\\log^2 k}\\right) + 2\\log\\left(1 - \\frac{3}{10} \\log k + O(\\log^2 k)\\right) - \\sum_{i=1}^{\\infty} c_i \\log^i k

    Formula f192, page 9, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (58). Returns the right-hand side (alpha_0(…) = …). O(…) remainder terms were dropped.

    Variables:
        c_i: the coefficients
    """
    return -math.log((4/9)*math.sqrt(6)*k/(math.sqrt(pi)*math.log(k)**2)) + 2*math.log(1 - 3/10*math.log(k)) - (builtins.sum(c_i*math.log(k)**i for i in range(1, math.inf+1)))


def eq_59_J(J_BS, k):
    """J'(k) = \\frac{1}{4} J'_{\\text{BS}}(k) = \\frac{3}{4k} \\log k \\left( 1 - \\frac{3}{10} \\log k + \\frac{109}{1,050} \\log^2 k + O(\\log^3 k) \\right).

    Formula f195, page 9, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (59). Returns the right-hand side (J(…) = …). O(…) remainder terms were dropped. Chained equation: only the first equality is used.

    Variables:
        J_BS: the rate function appearing in the statement of Proposition 1
    """
    return (1/4)*J_BS(k)


