def eq_78_v(rho):
    """v(\\rho) := \\frac{1}{\\rho^3} \\left( \\rho e^{2\\rho} - \\frac{3}{2} e^{2\\rho} + 2e^\\rho - \\frac{1}{2} \\right) = \\frac{1}{3} + \\frac{5}{12} \\rho + \\frac{17}{60} \\rho^3 + O(\\rho^4)

    Formula f273, page 11, section '3. SUBLEADING CORRECTIONS TO THE ASIAN IMPLIED VOLATILITY', equation (78). Returns the right-hand side (v(…) = …). O(…) remainder terms were dropped. Chained equation: only the first equality is used.
    """
    return (rho*math.exp(2*rho) - 3/2*math.exp(2*rho) + 2*math.exp(rho) - 1/2)/rho**3


def eq_81_C(A_f_dw, K, Phi, T, d_1, d_2, r):
    """C(K, T) = e^{-rT} [A_{\\text{fwd}} \\Phi(d_1) - K \\Phi(d_2)], \\quad P(K, T) = e^{-rT} [K \\Phi(-d_2) - A_{\\text{fwd}} \\Phi(-d_1)],

    Formula f291, page 12, section '4. NUMERICAL EXAMPLES', equation (81). Returns the right-hand side (C(…) = …). Text after the last top-level comma was ignored.

    Variables:
        r: a non-zero interest rate
    """
    return (A_f_dw*Phi(d_1) - K*Phi(d_2))*math.exp(-T*r)


def eq_84_c_4(mu):
    """c_4 = \\frac{11}{22,400}(\\mu + 1) - \\frac{2,897}{3,080,000}

    Formula f336, page 14, section '4. NUMERICAL EXAMPLES', equation (84). Returns the right-hand side (c_4 = …).
    """
    return (11/22400)*mu - 2897/3080000 + 11/22400


def eq_87_I(a, b, f, g, lambda_):
    """I(\\lambda) = \\int_a^b e^{-\\lambda f(x)} g(x) dx

    Formula f340, page 16, section 'APPENDIX A. ASYMPTOTIC EXPANSION FOR INTEGRALS', equation (87). Returns the right-hand side (I(…) = …).

    Variables:
        f: the gBM
    """
    return mpmath.quad(lambda x: g(x)*mpmath.exp(-lambda_*f(x)), (a, b))


def eq_90_d_0(a_0, alpha, b_0, beta):
    """d_0 = \\frac{b_0}{\\alpha a_0^{\\beta/\\alpha}}.

    Formula f358, page 16, section 'APPENDIX A. ASYMPTOTIC EXPANSION FOR INTEGRALS', equation (90). Returns the right-hand side (d_0 = …).

    Variables:
        beta: the solution of the equation $\\frac{\\sinh \\beta}{\\beta} = k$
    """
    return a_0**(-beta/alpha)*b_0/alpha

